static class ObjectCache {
    private final Path baseDir;
    ObjectCache(Path baseDir) { this.baseDir = baseDir; }

    void put(String key, Serializable obj) throws IOException {
        Path p = baseDir.resolve(key + ".ser");
        try (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(p.toFile()))) {
            out.writeObject(obj);
        }
    }

    Object get(String key) throws IOException, ClassNotFoundException {
        Path p = baseDir.resolve(key + ".ser");
        if (!Files.exists(p)) return null;
        try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(p.toFile()))) {
            return in.readObject();
        }
    }

    void delete(String key) throws IOException {
        Files.deleteIfExists(baseDir.resolve(key + ".ser"));
    }
}

