static class SimpleObjectDb<T extends Serializable> {
    private final Path file;
    SimpleObjectDb(Path file) { this.file = file; }

    void saveAll(List<T> records) throws IOException {
        try (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(file.toFile()))) {
            out.writeObject(new ArrayList<>(records));
        }
    }

    @SuppressWarnings("unchecked")
    List<T> loadAll() throws IOException, ClassNotFoundException {
        if (!Files.exists(file) || Files.size(file) == 0) return new ArrayList<>();
        try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(file.toFile()))) {
            return (List<T>) in.readObject();
        }
    }

    void append(T record) throws IOException, ClassNotFoundException {
        List<T> aktualne = loadAll();
        aktualne.add(record);
        saveAll(aktualne);
    }

    List<T> findBy(Predicate<T> predicate) throws IOException, ClassNotFoundException {
        return loadAll().stream().filter(predicate).toList();
    }
}
